import { useMemo } from 'react';

import { useRelations } from '@eventespresso/services';
import getIsLastRelatedEntity from './getIsLastRelatedEntity';

import type { RelationEntity } from '@eventespresso/services';
import type { EntityId } from '@eventespresso/data';

/**
 * Returns true if the given entity is the last one linked to any of its related entities.
 *
 * Pass `isLastEntity: true` to skip the relationship traversal and return true immediately —
 * useful when the caller (datetime/ticket) is only one.
 */
const useIsLastRelatedEntity = <E extends RelationEntity>(
	entity: E,
	entityId: EntityId,
	relation: Exclude<RelationEntity, E>,
	isLastEntity?: boolean
): boolean => {
	const { getRelations } = useRelations();

	return useMemo(() => {
		if (isLastEntity) return true;
		return getIsLastRelatedEntity(getRelations, entity, entityId, relation);
	}, [entity, entityId, relation, getRelations, isLastEntity]);
};

export default useIsLastRelatedEntity;
