import type { EntityId } from '@eventespresso/data';
import type { RelationEntity, useRelations } from '@eventespresso/services';

type GetRelations = ReturnType<typeof useRelations>['getRelations'];

/**
 * Returns true if deleting the given entity would leave any of its related entities
 * with no remaining references — meaning the deletion should be blocked.
 *
 * Single delete: checks whether this entity is the only one linked to any of its related entities.
 *
 * Bulk delete (pass `idsBeingDeleted`): evaluates the entire selected set together, so that
 * entities that are mutually last are correctly detected — e.g. two tickets both linked only to
 * the same datetime, or two datetimes both linked only to the same ticket, where deleting all of
 * them would leave the related entity with no remaining references.
 */
const getIsLastRelatedEntity = <E extends RelationEntity>(
	getRelations: GetRelations,
	entity: E,
	entityId: EntityId,
	relation: Exclude<RelationEntity, E>,
	idsBeingDeleted?: EntityId[]
): boolean => {
	const linkedIds = getRelations({ entity, entityId, relation });
	return linkedIds.some((linkedId) => {
		const reverseLinked = getRelations({
			entity: relation,
			entityId: linkedId,
			relation: entity as unknown as Exclude<RelationEntity, typeof relation>,
		});

		if (idsBeingDeleted) {
			// If every entity linked to this related entity is in the selected set, deleting them all
			// would leave it orphaned — so this entity must be blocked from deletion.
			return reverseLinked.filter((id) => !idsBeingDeleted.includes(id)).length === 0;
		}

		return reverseLinked.length === 1;
	});
};

export default getIsLastRelatedEntity;
