import { useMemo } from 'react';

import { useRelations } from '@eventespresso/services';
import getIsLastRelatedEntity from './getIsLastRelatedEntity';

import type { RelationEntity } from '@eventespresso/services';
import type { EntityId } from '@eventespresso/data';

/**
 * Given a list of entity IDs, returns only those that can be safely permanently deleted —
 * i.e. entities that are NOT the last one linked to any of their related entities.
 */
const useFilterDeletableEntities = <E extends RelationEntity>(
	entity: E,
	entityIds: EntityId[],
	relation: Exclude<RelationEntity, E>
): EntityId[] => {
	const { getRelations } = useRelations();

	return useMemo(
		() =>
			entityIds.filter(
				(entityId) => !getIsLastRelatedEntity(getRelations, entity, entityId, relation, entityIds)
			),
		[entity, entityIds, relation, getRelations]
	);
};

export default useFilterDeletableEntities;
